<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\User\Domain\ValueObject\Accessor\UserSecondFactorSeedAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserSecondFactorSeedAccessor trait.
 *
 * Covers null default, string/VO assignment via withSecondFactorSeed,
 * getSecondFactorSeed/secondFactorSeed accessors, and isSecondFactorSeedChanged with/without original.
 */
class UserSecondFactorSeedAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withSecondFactorSeed creates a new instance with the SecondFactorSeed set
     * from a string value, and getSecondFactorSeed returns the primitive string.
     */
    public function testWithSecondFactorSeedFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserSecondFactorSeedAccessorUnitTest();

        // Act
        $result = $holder->withSecondFactorSeed('cyphered://cypher');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('****er', $result->getSecondFactorSeed());
    }
    /**
     * Asserts that withsecondFactorSeed has access to the value object
     * from a string value, and getSecondFactorSeed returns the primitive string.
     */
    public function testWithSecondFactorSeedFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserSecondFactorSeedAccessorUnitTest();

        // Act
        $result = $holder->withSecondFactorSeed('cyphered://cypher');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('****er', $result->secondFactorSeed()->value());
    }
    public function testChangedSecondFactorSeed(): void
    {
        // Arrange
        $holder = new ImplWithUserSecondFactorSeedAccessorUnitTest();
        $original = $holder->withSecondFactorSeed('cyphered://cypher');
        $same = $holder->withSecondFactorSeed('cyphered://cypher');
        $modified = $holder->withSecondFactorSeed('cyphered://ocyphered');

        // Act
        $unchanged = $holder->isSecondFactorSeedChanged();
        $withSame = $original->isSecondFactorSeedChanged($same);
        $withDiferent = $original->isSecondFactorSeedChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserSecondFactorSeedAccessorUnitTest
{
    use UserSecondFactorSeedAccessor;
}
